class Zipper:
    """An immutable focus in a binary tree of value/left/right dictionaries."""

    def __init__(self, tree, parents=()):
        self._tree = tree
        self._parents = parents

    @staticmethod
    def from_tree(tree):
        """Focus on the root, or return None for an empty tree."""
        if tree is None:
            return None
        return Zipper(deepcopy(tree))

    def value(self):
        return deepcopy(self._tree["value"])

    def set_value(self, value):
        return self._replace("value", value)

    def left(self):
        return self._down("left")

    def set_left(self, tree):
        return self._replace("left", tree)

    def right(self):
        return self._down("right")

    def set_right(self, tree):
        return self._replace("right", tree)

    def up(self):
        if not self._parents:
            return None
        direction, parent = self._parents[-1]
        tree = dict(parent)
        tree[direction] = self._tree
        return Zipper(tree, self._parents[:-1])

    def to_tree(self):
        """Return the entire tree, including edits below the root."""
        zipper = self
        while zipper._parents:
            zipper = zipper.up()
        return deepcopy(zipper._tree)

    def _replace(self, key, value):
        tree = dict(self._tree)
        tree[key] = deepcopy(value)
        return Zipper(tree, self._parents)

    def _down(self, direction):
        child = self._tree[direction]
        if child is None:
            return None
        parents = self._parents + ((direction, self._tree),)
        return Zipper(child, parents)
